INSERT INTO `questions` (`id`, `code`, `course_id`, `question_bank_id`, `question_group_id`, `content`, `type`, `difficulty`, `default_score`, `explanation`, `feedback`, `general_feedback`, `metadata`, `created_at`, `updated_at`) VALUES (1,'Q-C1-A489B0',1,1,1,'Kiến thức cốt lõi của học phần «Khoá học 01» thường tập trung vào điều gì?','single_choice',1,1.00,'Mỗi học phần có mục tiêu kiến thức/kỹ năng riêng — với «Khoá học 01» cần nắm phần đặc thù của môn.',NULL,NULL,NULL,'2026-08-12 15:53:46','2026-08-12 15:53:46'),(2,'Q-C1-A55D78',1,1,1,'Khi ôn tập cuối khóa «Khoá học 01», cách hiệu quả nhất là gì?','single_choice',1,1.00,'Ôn có cấu trúc giúp bao phủ đúng chuẩn đầu ra.',NULL,NULL,NULL,'2026-08-12 15:53:46','2026-08-12 15:53:46'),(3,'Q-C1-A616A9',1,1,1,'Kết quả học phần «Khoá học 01» thường được đánh giá dựa trên?','single_choice',1,1.00,'Đánh giá bám chuẩn đầu ra học phần.',NULL,NULL,NULL,'2026-08-12 15:53:46','2026-08-12 15:53:46'),(4,'Q-C1-A6CDFE',1,1,1,'Nếu một khái niệm trong «Khoá học 01» chưa rõ, bạn nên?','single_choice',2,1.00,'Làm rõ khái niệm bằng tài liệu chuẩn + luyện tập.',NULL,NULL,NULL,'2026-08-12 15:53:46','2026-08-12 15:53:46'),(5,'Q-C1-A766EB',1,1,1,'Phần thực hành của «Khoá học 01» có vai trò gì?','single_choice',2,1.00,'Thực hành gắn lý thuyết với kỹ năng.',NULL,NULL,NULL,'2026-08-12 15:53:46','2026-08-12 15:53:46'),(6,'Q-C1-A8141C',1,1,1,'Trước kỳ thi «Khoá học 01», nên ưu tiên?','single_choice',2,1.00,'Ưu tiên theo ma trận đề cương.',NULL,NULL,NULL,'2026-08-12 15:53:46','2026-08-12 15:53:46'),(7,'Q-C1-A8D61C',1,1,1,'Tài liệu chính đáng tin cậy cho «Khoá học 01» thường là?','single_choice',1,1.00,'Bám nguồn chính thống của học phần.',NULL,NULL,NULL,'2026-08-12 15:53:46','2026-08-12 15:53:46'),(8,'Q-C1-A992BB',1,1,1,'Khi làm bài tập «Khoá học 01», bước hợp lý là?','single_choice',2,1.00,'Quy trình giải có kiểm chứng giảm sai sót.',NULL,NULL,NULL,'2026-08-12 15:53:46','2026-08-12 15:53:46'),(9,'Q-C1-AA593E',1,1,1,'Mục tiêu cuối của học phần «Khoá